namespace DaisysApp.Applets.SimEffects.Binder.Formats.Fso;

/// <summary>Control config tabs, as in FSO's CC_tab.</summary>
public enum Tab { None, Targeting, Ship, Weapons, Computer }

/// <summary>FSO's CC_type.</summary>
public enum CcType { Trigger, Continuous, AxisAbs, AxisRel }

/// <summary>
/// One FSO control action with its engine defaults. <see cref="Id"/> is the IoActionId value and
/// <see cref="Name"/> is the enum name used in preset files and controlconfigdefaults.tbl.
/// </summary>
public sealed record ActionDef(
    string Name, int Id, Tab Tab, CcType Type, int XstrIndex, string Text, bool Disabled, FsoBind Primary, FsoBind Secondary)
{
    public bool IsAxis => Type is CcType.AxisAbs or CcType.AxisRel;
}

